from booking import cancellation_fee


def test_cancellation_fee_at_and_above_threshold():
    for hours in (24, 25, 48):
        result = cancellation_fee(hours)
        assert isinstance(result, int) and not isinstance(result, bool)
        assert result == 0

from booking import cancellation_fee


def test_cancellation_fee_within_24_hours():
    for hours in (0, 23, 12):
        result = cancellation_fee(hours)
        assert isinstance(result, int) and not isinstance(result, bool)
        assert result == 2500

